<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {ServiceProvider} from '@/services/service-provider';import type {User} from '@/types/user';const props=defineProps<{id:string}>();const router=useRouter();const user=ref<User>();const error=ref('');onMounted(async()=>{try{user.value=await ServiceProvider.users.getById(Number(props.id))}catch(e){error.value=(e as Error).message}})</script>
<template><section class="narrow"><RouterLink class="back" to="/users">← До списку</RouterLink><p v-if="error" class="error">{{error}}</p><div v-if="user" class="card profile"><img :src="user.image" alt=""/><div><p class="eyebrow">USER #{{user.id}}</p><h1>{{user.firstName}} {{user.lastName}}</h1><p>{{user.email}} · {{user.phone}}</p><p><b>Username:</b> {{user.username}} · <b>Age:</b> {{user.age}} · <b>Gender:</b> {{user.gender}}</p><p v-if="user.address"><b>Address:</b> {{user.address.address}}, {{user.address.city}}</p><div class="actions"><RouterLink class="button" :to="`/users/${user.id}/edit`">Редагувати</RouterLink><button class="button secondary" @click="router.push('/users')">Назад</button></div></div></div></section></template>
